"use client";

import { useMemo, useState, type ReactNode } from "react";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ChevronLeft, ChevronRight } from "lucide-react";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
  useDataGridActions,
  useDataGridVisibleColumns,
} from "@/registry/default/components/data-grid/data-grid";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 150, flex: 2, reorderable: false },
  {
    id: "role",
    header: "Role",
    accessorKey: "role",
    type: "select",
    options: {
      choices: [
        "Admin",
        "User",
        "Editor",
        "Viewer",
        "Manager",
      ],
    },
    width: 110,
    flex: 1,
  },
  { id: "age", header: "Age", accessorKey: "age", type: "number", options: { min: 18, max: 100 }, width: 80, flex: 1 },
  { id: "joined", header: "Joined", accessorKey: "joined", type: "date", width: 110, flex: 1 },
  { id: "score", header: "Logins (30 days)", accessorKey: "score", type: "number", options: { min: 0, max: 100 }, width: 80, flex: 1, pin: "end" },
] as const);

/** Pick a column + move it one step left/right through the programmatic `setColumnOrder` path. */
function ReorderControls(): ReactNode {
  const actions = useDataGridActions();
  const visible = useDataGridVisibleColumns<DemoRow>();
  const [selectedId, setSelectedId] = useState<string | null>(() => visible[1]?.id ?? visible[0]?.id ?? null);
  const index = selectedId === null ? -1 : visible.findIndex((column) => column.id === selectedId);

  const moveArgs = (step: -1 | 1) => {
    const target = visible[index + step];
    return selectedId === null || index === -1 || !target ? undefined : ([selectedId, target.id, step === -1 ? "before" : "after"] as const);
  };
  const canMove = (step: -1 | 1) => {
    const args = moveArgs(step);
    return args !== undefined && actions.canSetColumnOrder(...args).ok;
  };
  const move = (step: -1 | 1) => {
    const args = moveArgs(step);
    if (args) actions.setColumnOrder(...args);
  };

  if (visible.length < 2) return null;

  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-sm text-muted-foreground">Move</span>
      <Select value={selectedId} onValueChange={setSelectedId}>
        <SelectTrigger className="h-8 w-40" aria-label="Column to move">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {visible.map((column) => (
            <SelectItem key={column.id} value={column.id}>
              {column.header}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Button variant="outline" size="sm" disabled={!canMove(-1)} onClick={() => move(-1)}>
        <ChevronLeft className="size-4" /> Left
      </Button>
      <Button variant="outline" size="sm" disabled={!canMove(1)} onClick={() => move(1)}>
        Right <ChevronRight className="size-4" />
      </Button>
    </div>
  );
}

/**
 * Column drag & drop: `enableColumnReorder` lets a header drag within its pin zone (Name opts
 * out via `reorderable: false`, Logins is end-pinned and moves only with the pinned zone), and
 * the picker + buttons show the programmatic `setColumnOrder(id, targetId, position)` path.
 */
export default function DataGridColumnDragDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(10), []);

  return (
    <div className="w-full flex flex-col gap-3">
      <p className="text-sm text-muted-foreground">
        Drag a header to reorder it — the move stays inside its pin zone. Name cannot be moved
        (<code>reorderable: false</code>) and Logins is pinned to the end. The picker below the line
        moves the chosen column programmatically.
      </p>
      <DataGridProvider defaultData={rows} columns={columns} enableColumnReorder>
        <ReorderControls />
        <div className="h-[340px] overflow-hidden rounded-md border border-border">
          <DataGridRoot className="h-full rounded-none border-none">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </div>
      </DataGridProvider>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
